def is_good_set(U):
    """Checks if a set U is a good set."""
    n = len(U)
    if n < 3:
        return False

    # Condition 1: GCD of any three distinct elements is 1
    for triple in combinations(U, 3):
        if gcd_three(*triple) != 1:
            return False

    # Condition 2: For any two distinct elements, there exists another element that is a divisor of their product.
    U_list = list(U)
    for i in range(n):
        for j in range(i + 1, n):
            x = U_list[i]
            y = U_list[j]
            product = x * y
            found_divisor = False
            for z in U_list:
                # z must be distinct from x and y only if the problem implies z != x and z != y.
                # "there exists another element that is a divisor of their product."
                # If z can be x or y, the condition is trivial (x | xy, y | xy).
                # Usually "another element" means z must be one of the elements in U, which it is.
                # Let's test the standard interpretation: z is an element of U.
                # If we allow z=x or z=y, the condition is always true since x|xy and y|xy.
                # This must mean z is NOT x AND z is NOT y, OR the problem statement is flawed/trivial.
                # Let's assume z must be distinct from x and y, if possible, otherwise the condition is trivial.

                if z != x and z != y and product % z == 0:
                    found_divisor = True
                    break

            # If we restrict z to be distinct from x and y, and no such z exists, the set fails.
            # If n=3, U={x, y, z}. Pair (x, y). z must divide xy.
            if n == 3:
                z_third = [u for u in U if u != x and u != y][0]
                if product % z_third != 0:
                    return False
            else:
                # For |U| > 3, if we couldn't find a distinct divisor z, the condition fails.
                if not found_divisor:
                    return False

    return True

