import math
from itertools import combinations

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def gcd_three(a, b, c):
    return gcd(a, gcd(b, c))

def is_good_set(U):
    if len(U) < 3:
        return False

    # Condition 1: GCD of any three distinct elements is 1.
    # Since |U| >= 3, we only check this if |U| > 3. If |U|=3, this is trivial.
    if len(U) > 3:
        for subset in combinations(U, 3):
            if gcd_three(*subset) != 1:
                return False

    # Condition 2: For any two distinct elements, there exists another element that is a divisor of their product.
    elements = U
    n = len(elements)

    for i in range(n):
        for j in range(i + 1, n):
            u_i = elements[i]
            u_j = elements[j]

            # Check the remaining elements (u_k where k != i and k != j)
            found_divisor = False
            for k in range(n):
                if k != i and k != j:
                    u_k = elements[k]
                    if (u_i * u_j) % u_k == 0:
                        found_divisor = True
                        break

            if not found_divisor:
                return False

    return True

